create table xxventuri.crm_sales_orders_temp (
    order_id               number,
    order_number           number,
    customer_unique_id     number,
    customer_id            varchar2(255 byte),
    po_number              varchar2(100 byte),
    po_date                date,
    reference              varchar2(100 byte),
    billing_location       varchar2(255 byte),
    delivery_location      varchar2(255 byte),
    order_date             date,
    remarks                varchar2(100 byte),
    order_products_id      varchar2(255 byte),
    brand_id               number,
    product_id             varchar2(255 byte),
    staff_code             varchar2(255 byte),
    product_name           varchar2(255 byte),
    quantity               number,
    product_price          number,
    currency_type          varchar2(50 byte),
    delivery_date          date,
    customer_name          varchar2(255 byte),
    gst_no                 varchar2(100 byte),
    customer_address1      varchar2(255 byte),
    customer_address2      varchar2(255 byte),
    customer_location_name varchar2(255 byte),
    updated_in_tally       varchar2(1 byte)
);


